<template><div class="admin-applications-page"><AdminApplicationsTabs active="reviews"/><DemoIdentitySwitcher/><div v-if="identity.role!=='admin'" class="applications-queue applications-state"><strong>Admin demo view required</strong><p>Organisation-wide reviewer identities, scores, and decisions are not available to reviewer previews.</p></div><template v-else><header class="applications-page-header"><div><h1>Review progress</h1><p>Authorised operational status, reviewer identity, and submitted weighted results.</p></div><span class="demo-data-badge">Demo data</span></header><section class="review-summary-groups" aria-label="Review progress summary"><article v-for="x in dashboard.summary" :key="x.label"><strong>{{x.value}}</strong><span>{{x.label}}</span></article></section><section class="application-panel review-pipeline"><h2>Review pipeline</h2><ol><li v-for="(x,i) in dashboard.pipeline" :key="x.label"><span>{{i+1}}</span><strong>{{x.label}}</strong><small>{{x.count}} applications</small></li></ol></section><form class="review-dashboard-filters" @submit.prevent><label><span>Search applicant or reference</span><input v-model="filters.search" type="search"/></label><label><span>Current phase</span><select v-model="filters.phase"><option value="">All phases</option><option v-for="x in dashboard.pipeline" :key="x.label">{{x.label}}</option></select></label><label><span>Reviews completed</span><select v-model="filters.completed"><option value="">Any number</option><option v-for="n in 4" :key="n-1" :value="n-1">{{n-1}}</option></select></label><label><span>Workflow flag</span><select v-model="filters.flag"><option value="">Any state</option><option value="concern">Serious concern</option><option value="early">Early acceptance eligible</option><option value="admin">Admin action required</option></select></label></form><section v-for="r in filtered" :key="r.application.id" class="application-panel review-progress-record"><header><div><h2>{{r.application.applicantName}}</h2><p>{{r.application.reference}} · {{r.application.pathwayLabel}}</p></div><RouterLink class="application-action-link" :to="{name:'AdminApplicationDetail',params:{applicationId:r.application.id}}">View review details</RouterLink></header><div v-if="r.ownIndependent&&!r.scoresVisible" class="independent-score-guard"><strong>Scores hidden while your independent review is in progress</strong><p>Reviewer identities and completion states remain visible, but peer scores and the combined percentage are withheld.</p><button type="button" @click="pendingReveal=r.application">Reveal scores and continue as an informed reviewer</button></div><div class="reviewer-slot-table"><article v-for="slot in r.slots" :key="slot.slot"><span>Reviewer {{slot.slot}}</span><strong>{{slot.reviewerName||'Available'}}</strong><small>{{slotText(slot,r.scoresVisible)}}</small><small>{{slot.reviewLabel}}</small><small v-if="slot.claimedAt">Claimed {{date(slot.claimedAt)}}</small><small v-if="slot.submittedAt">Submitted {{date(slot.submittedAt)}}</small><span v-if="slot.seriousConcern" class="concern-warning">Serious concern</span><span v-if="slot.clarification" class="clarification-flag">Clarification recorded</span></article></div><dl class="admin-progress-metrics"><div><dt>Review progress</dt><dd>{{r.claimed}} of 3 claimed · {{r.completed}} completed</dd></div><div><dt>Combined percentage</dt><dd>{{r.combinedPercentage===null?(r.scoresVisible?'Available after final completion':'Hidden during independent review'):pct(r.combinedPercentage)}}</dd></div><div><dt>Outcome</dt><dd>{{r.decision}}</dd></div><div><dt>Early acceptance</dt><dd>{{r.earlyEligible?'Eligible':'Not currently eligible'}}</dd></div><div><dt>Override</dt><dd>{{r.concern?'Concern or clarification requires Admin response':'No blocking concern'}}</dd></div><div><dt>Next action</dt><dd>{{r.nextAction}}</dd></div></dl></section><p v-if="!filtered.length" class="applications-state">No applications match these filters.</p><DemoActionModal v-if="pendingReveal" title="Reveal completed review scores" description="Your unfinished Admin review will permanently become an informed admin review." warning="This action is audited and independence cannot be restored by hiding the scores again." confirm-label="Reveal and continue informed" @cancel="pendingReveal=null" @confirm="confirmReveal"/></template></div></template>
<script>import AdminApplicationsTabs from'./components/AdminApplicationsTabs.vue';import DemoIdentitySwitcher from'./components/DemoIdentitySwitcher.vue';import DemoActionModal from'./components/DemoActionModal.vue';import{demoWorkflow,getDemoIdentity,getReviewDashboard,listAdminApplications,revealCompletedReviews}from'./applicationAdminData.js';export default{name:'AdminApplicationReviews',components:{AdminApplicationsTabs,DemoIdentitySwitcher,DemoActionModal},data:()=>({workflow:demoWorkflow,applications:[],pendingReveal:null,filters:{search:'',phase:'',completed:'',flag:''}}),computed:{identity(){this.workflow.revision;return getDemoIdentity()},dashboard(){this.workflow.revision;return getReviewDashboard(this.applications)},filtered(){const q=this.filters.search.toLowerCase();return this.dashboard.records.filter(r=>(!q||`${r.application.applicantName} ${r.application.reference}`.toLowerCase().includes(q))&&(!this.filters.phase||r.phase===this.filters.phase)&&(this.filters.completed===''||r.completed===Number(this.filters.completed))&&(!this.filters.flag||(this.filters.flag==='concern'&&r.concern)||(this.filters.flag==='early'&&r.earlyEligible)||(this.filters.flag==='admin'&&r.adminRequired))) }},async mounted(){this.applications=await listAdminApplications()},methods:{pct(v){return`${Number(v).toFixed(1)}%`},date(v){return new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v))},slotText(s,visible){if(s.state==='available')return'Available';if(s.state==='closed')return'Closed because third review was waived';if(s.state==='claimed')return`Claimed by ${s.reviewerName}`;if(s.state==='in-progress')return'In progress';if(s.state==='submitted')return visible?`Submitted — ${this.pct(s.percentage)}`:'Submitted — score hidden';return s.state},confirmReveal(){revealCompletedReviews();this.pendingReveal=null}}};</script><style src="./AdminApplications.css"></style>
